(6808125, 1020724, 140305, '<td valign="top">So beautiful! I tried to take this kind of shot while on vacation in Hawaii and quickly realized how much skill it takes to do it properly. I never got a great shot unfortunately, but this inspires me to keep trying. Lovely image.</td>', 'So beautiful! I tried to take this kind of shot while on vacation in Hawaii and quickly realized how much skill it takes to do it properly. I never got a great shot unfortunately, but this inspires me to keep trying. Lovely image.', '2012-07-03 23:00:20.000000', NULL, 1),
(6808126, 1021349, 112739, '<td valign="top">Wonderful catch mate! Lovely shot.</td>', 'Wonderful catch mate! Lovely shot.', '2012-07-03 23:00:20.000000', NULL, 1),
(6808131, 1022411, 112739, '<td valign="top">A lot of times, these types of landscape/water shots at sunset have a quality that makes it a little difficult to view for more than a couple seconds, but this one is very well done and very balanced. Make me feel like I am standing right there. Well done.</td>', 'A lot of times, these types of landscape/water shots at sunset have a quality that makes it a little difficult to view for more than a couple seconds, but this one is very well done and very balanced. Make me feel like I am standing right there. Well done.', '2012-07-03 23:07:35.000000', NULL, 1),
(6808132, 1023405, 112739, '<td valign="top">Very minimal. That water looks like sand. Maybe it is sand? 8</td>', 'Very minimal. That water looks like sand. Maybe it is sand? 8', '2012-07-03 23:09:29.000000', NULL, 1),
