INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6808370, 1022409, 9387, '<td valign="top">Very well done. Love the muted colors and the composition. Great capture and processing by you.</td>', 'Very well done. Love the muted colors and the composition. Great capture and processing by you.', '2012-07-04 02:57:54.000000', NULL, 1),
(6808371, 1022323, 9387, '<td valign="top">I like the one flower that is in focus. That is well done. However, my personal opinion is that I would have blacked the rest of the picture out. To me it is disturbing because the unfocused things in the rest of the shot are taking my focus away from the lovely flower. I understand that everyone has their own vision but this is just what I feel.</td>', 'I like the one flower that is in focus. That is well done. However, my personal opinion is that I would have blacked the rest of the picture out. To me it is disturbing because the unfocused things in the rest of the shot are taking my focus away from the lovely flower. I understand that everyone has their own vision but this is just what I feel.', '2012-07-04 03:00:11.000000', NULL, 1),
(6808372, 1023422, 9387, '<td valign="top">Good rule of thirds,  but I would have preferred more detail in the black areas. Just my opinion.</td>', 'Good rule of thirds,  but I would have preferred more detail in the black areas. Just my opinion.', '2012-07-04 03:01:13.000000', NULL, 1),
(6808373, 1023606, 9387, '<td valign="top">Great shot of the kitten and it''s mother (my assumption. Well done.</td>', 'Great shot of the kitten and it''s mother (my assumption. Well done.', '2012-07-04 03:01:49.000000', NULL, 1),
(6808374, 1023733, 9387, '<td valign="top">Very nice composition and good lighting. Love the slice of the moon. Well done.</td>', 'Very nice composition and good lighting. Love the slice of the moon. Well done.', '2012-07-04 03:02:21.000000', NULL, 1),
(6808375, 1023649, 9387, '<td valign="top">Very well done. Great idea and great processing.</td>', 'Very well done. Great idea and great processing.', '2012-07-04 03:02:53.000000', NULL, 1),
(6808377, 1022411, 9387, '<td valign="top">This is wonderful. The blues are great as are the trees. The toning is very well done and the shot is very  soothing. A job well done by you.</td>', 'This is wonderful. The blues are great as are the trees. The toning is very well done and the shot is very  soothing. A job well done by you.', '2012-07-04 03:03:56.000000', NULL, 1),
(6808378, 1023501, 9387, '<td valign="top">Nice vision and execution.</td>', 'Nice vision and execution.', '2012-07-04 03:04:14.000000', NULL, 1),
(6808379, 1020827, 9387, '<td valign="top">Not enough clarity on the bird and most of it is over exposed.</td>', 'Not enough clarity on the bird and most of it is over exposed.', '2012-07-04 03:04:59.000000', NULL, 1),
(6808380, 1023563, 9387, '<td valign="top">Great shot.</td>', 'Great shot.', '2012-07-04 03:05:13.000000', NULL, 1),
(6808381, 1019623, 9387, '<td valign="top">Very interesting and artfully done. Nice tones and textures.</td>', 'Very interesting and artfully done. Nice tones and textures.', '2012-07-04 03:05:56.000000', NULL, 1),
(6808382, 1023510, 9387, '<td valign="top">Well done. Nice composition, An appealing shot.</td>', 'Well done. Nice composition, An appealing shot.', '2012-07-04 03:06:37.000000', NULL, 1),
(6808383, 1022901, 9387, '<td valign="top">to me this shot is too overexposed.</td>', 'to me this shot is too overexposed.', '2012-07-04 03:07:00.000000', NULL, 1),
(6808386, 1023703, 9387, '<td valign="top">This could have been an excellent shot but in black and white the clouds are taking over and one can barely see the boats and the piers.  They are almost a distraction to the sky.  Maybe if you had lightened a few parts of it the whole scene would have had a better impact. I''m sure your vision for this shot is different than mine and I don''t want you to think that I don''t like it. I just wanted a little more.</td>', 'This could have been an excellent shot but in black and white the clouds are taking over and one can barely see the boats and the piers.  They are almost a distraction to the sky.  Maybe if you had lightened a few parts of it the whole scene would have had a better impact. I''m sure your vision for this shot is different than mine and I don''t want you to think that I don''t like it. I just wanted a little more.', '2012-07-04 03:09:51.000000', NULL, 1),
(6808387, 1021806, 9387, '<td valign="top">Very well done. Great tones for a black &amp; white shot. Good clarity and textures. Great portrait of the three people. Nice tones and very well done.</td>', 'Very well done. Great tones for a black & white shot. Good clarity and textures. Great portrait of the three people. Nice tones and very well done.', '2012-07-04 03:10:46.000000', NULL, 1),
(6808388, 1021242, 9387, '<td valign="top">Too out of focus for me. I would have like to see one thing in focus.</td>', 'Too out of focus for me. I would have like to see one thing in focus.', '2012-07-04 03:11:12.000000', NULL, 1),
(6808389, 1023514, 9387, '<td valign="top">I"m not sure how I feel about this. I like the part that I see but I think there is too much that I don''t see on this canvas.</td>', 'I"m not sure how I feel about this. I like the part that I see but I think there is too much that I don''t see on this canvas.', '2012-07-04 03:12:10.000000', NULL, 1),
(6808391, 1023278, 9387, '<td valign="top">Great composition. Very artistic take on the subject. Great detail and clarity. Nice tones. Well done.</td>', 'Great composition. Very artistic take on the subject. Great detail and clarity. Nice tones. Well done.', '2012-07-04 03:12:56.000000', NULL, 1),
(6808392, 1018930, 9387, '<td valign="top">This is a nice shot but I prefer that the sky not be so over exposed.</td>', 'This is a nice shot but I prefer that the sky not be so over exposed.', '2012-07-04 03:13:43.000000', NULL, 1),
(6808393, 1023728, 9387, '<td valign="top">Great action shot but I would have preferred it a little lighter instead of so dark that you can''t really make out some of the details.</td>', 'Great action shot but I would have preferred it a little lighter instead of so dark that you can''t really make out some of the details.', '2012-07-04 03:14:45.000000', NULL, 1),
(6808394, 1023743, 9387, '<td valign="top">Too over exposed.</td>', 'Too over exposed.', '2012-07-04 03:15:00.000000', NULL, 1),
(6808395, 1023320, 9387, '<td valign="top">Great capture. Great clarity and texture in the feathers. Well done.</td>', 'Great capture. Great clarity and texture in the feathers. Well done.', '2012-07-04 03:15:44.000000', NULL, 1),
(6808397, 1023648, 9387, '<td valign="top">I would have liked to see the butterfly in more detail. If I hadn''t read the title I might not have even noticed that it was a butterfly. The flower is in good focus.</td>', 'I would have liked to see the butterfly in more detail. If I hadn''t read the title I might not have even noticed that it was a butterfly. The flower is in good focus.', '2012-07-04 03:17:26.000000', NULL, 1),
(6808398, 1023553, 9387, '<td valign="top">Great capture. Very well done. Nice composition, nice tones and very appealing.</td>', 'Great capture. Very well done. Nice composition, nice tones and very appealing.', '2012-07-04 03:18:02.000000', NULL, 1),
(6808399, 1020185, 114233, '<td valign="top">Nicely Done Rian!<br/>I think you have managed to blend the rocks nicely - more detail in the ones closest to you and more of a silhouette for the ones closest to the sun. The choice of shutter speed is simply great and I''m sure others will comment on the same fact.<br/>Sharpening looks natural so well done there.<br/>Above all, the composition is magnificent. Our eyes are taken on a journey from splash to splash following the movement of the water and then out to see where the waves are waiting to come in again.<br/>I hope this does well and that it reminds you of the nice weekend you had down there and the great achievement of completing the Comrades as well. It may not seem much to you but for us mere mortals it is something to behold.</td>', 'Nicely Done Rian!I think you have managed to blend the rocks nicely - more detail in the ones closest to you and more of a silhouette for the ones closest to the sun. The choice of shutter speed is simply great and I''m sure others will comment on the same fact.Sharpening looks natural so well done there.Above all, the composition is magnificent. Our eyes are taken on a journey from splash to splash following the movement of the water and then out to see where the waves are waiting to come in again.I hope this does well and that it reminds you of the nice weekend you had down there and the great achievement of completing the Comrades as well. It may not seem much to you but for us mere mortals it is something to behold.', '2012-07-04 03:18:29.000000', NULL, 1),
(6808400, 1023764, 9387, '<td valign="top">Nice black &amp; white. Good detail on the step wall but a little over exposed on the sky and the actual steps.</td>', 'Nice black & white. Good detail on the step wall but a little over exposed on the sky and the actual steps.', '2012-07-04 03:18:42.000000', NULL, 1),
(6808401, 1023682, 9387, '<td valign="top">Great capture, nice composition and good detail.</td>', 'Great capture, nice composition and good detail.', '2012-07-04 03:19:04.000000', NULL, 1),
(6808402, 1020542, 9387, '<td valign="top">I am not fond of this. It looks too overdone if that is possible. I will take away a point from you and take away a point from me as I feel everyone needs to express themselves.</td>', 'I am not fond of this. It looks too overdone if that is possible. I will take away a point from you and take away a point from me as I feel everyone needs to express themselves.', '2012-07-04 03:20:53.000000', NULL, 1),
(6808403, 1023135, 9387, '<td valign="top">The lighting isn''t right on this shot. The yellows are overexposed, the reds have streaks of light on them - the backis okay.</td>', 'The lighting isn''t right on this shot. The yellows are overexposed, the reds have streaks of light on them - the backis okay.', '2012-07-04 03:21:58.000000', NULL, 1),
