(6814090, 1022037, 86218, '<td valign="top">Such a strong atmosphere about this shot Tom. 1 Bright red umbrella poppoing through the gras bottom third would have been an interesting take but thats another pic on it''s own and this image needs to be there as well...the secluded, mystery of the house in the mist.</td>', 'Such a strong atmosphere about this shot Tom. 1 Bright red umbrella poppoing through the gras bottom third would have been an interesting take but thats another pic on it''s own and this image needs to be there as well...the secluded, mystery of the house in the mist.', '2012-07-10 01:58:44.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6814123, 1023419, 86218, '<td valign="top">Wow... Great photography. You certainly have guts to do this. I have done this in the past taking pictures of people but I often feel like a scoundrel doing it, like I stole something from the person. Something i suppose I have to deal with but cant do this freely. Glad he gave you the nod of approval</td>', 'Wow... Great photography. You certainly have guts to do this. I have done this in the past taking pictures of people but I often feel like a scoundrel doing it, like I stole something from the person. Something i suppose I have to deal with but cant do this freely. Glad he gave you the nod of approval', '2012-07-10 03:07:51.000000', NULL, 0),
(6814158, 1023421, 113156, '<td valign="top">You must pop in and say hello if you come down south, nice one.</td>', 'You must pop in and say hello if you come down south, nice one.', '2012-07-10 06:07:47.000000', NULL, 0),
(6814394, 1023607, 94265, '<td valign="top">I hoped this would be in the top 10, I loved it. Fab shot all round.</td>', 'I hoped this would be in the top 10, I loved it. Fab shot all round.', '2012-07-10 12:20:52.000000', NULL, 0),
(6814412, 1021860, 133853, '<td valign="top">@JunieMoon you don''t think the car is sharp? With reference to motion blur (as I know this is a Photoshop filter effect), the blur has come directly from the RAW file and has not been edited at all... bar some minor adjustments in lightroom.<br/> <br/>Thanks tanguera and others, it was not an easy shot... maybe not everyone''s cup of tea though it seems.<br/> <br/>=)</td>', '@JunieMoon you don''t think the car is sharp? With reference to motion blur (as I know this is a Photoshop filter effect), the blur has come directly from the RAW file and has not been edited at all... bar some minor adjustments in lightroom. Thanks tanguera and others, it was not an easy shot... maybe not everyone''s cup of tea though it seems. =)', '2012-07-10 12:28:04.000000', NULL, 0),
